const cache = {};
/** Alamat gambar logo bank, atau null bila logonya belum ada. */
export function logoSrc(id) {
  const l = LOGO[id];
  if (!l) return null;
  if (!cache[id]) cache[id] = l.svg ? URL.createObjectURL(new Blob([l.svg], { type: 'image/svg+xml' })) : `data:image/webp;base64,${l.webp}`;
  return cache[id];
}
